<script setup lang="ts">
import OfficialReplyEditor from './OfficialReplyEditor.vue'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleDrawer from '../console/ConsoleDrawer.vue'
import ConsoleValidatedForm from '../console/ConsoleValidatedForm.vue'
import ConsoleDiscardChangesDialog from '../console/ConsoleDiscardChangesDialog.vue'
import type {OfficialReplies,OfficialKeyword} from '~/types/official-account'
const emit=defineEmits<{busy:[value:boolean]}>(),mediaBusy=ref(false)
function pending(value:boolean){mediaBusy.value=value;emit('busy',value)}
const props=defineProps<{disabled:boolean}>(),model=defineModel<OfficialReplies>({required:true}),tab=useRouteTab<string>('keywords',['keywords','fallback','welcome'],'replyTab'),open=ref(false),error=ref(''),editing=ref<string|null>(null),baseline=ref(''),draft=ref<OfficialKeyword>({id:'',name:'',keyword:'',match:'exact',enabled:true,text:''}),discard=useDiscardChanges(()=>mediaBusy.value)
const dirty=computed(()=>JSON.stringify(draft.value)!==baseline.value)
function edit(row?:OfficialKeyword){if(props.disabled)return;editing.value=row?.id||null;draft.value=row?{...row}:{id:crypto.randomUUID(),name:'',keyword:'',match:'exact',enabled:true,text:''};baseline.value=JSON.stringify(draft.value);error.value='';open.value=true}
function cancel(){draft.value=JSON.parse(baseline.value);open.value=false;discard.keep()}
function close(){if(mediaBusy.value)return;if(dirty.value){discard.request(cancel);return}open.value=false}
function save(){if(props.disabled||mediaBusy.value)return;if(!draft.value.name.trim()||!draft.value.keyword.trim()){error.value='请填写规则名称和关键词';return}if(model.value.keywords.some(r=>r.id!==editing.value&&r.enabled&&draft.value.enabled&&r.keyword===draft.value.keyword&&r.match===draft.value.match)){error.value='已存在相同的关键词规则';return}const r=draft.value,type=r.type||'text',complete=type==='text'?!!r.text.trim():type==='image'||type==='video'?!!r.materialId:type==='news'?!!r.title&&!!r.url&&!!r.coverMaterialId:!!r.appId&&!!r.title&&!!r.pagePath&&!!r.coverMaterialId;if(!complete){error.value='请填写完整回复内容';return}const i=model.value.keywords.findIndex(r=>r.id===editing.value);if(i>=0)model.value.keywords[i]={...draft.value};else model.value.keywords.push({...draft.value});open.value=false}
usePageLeaveGuard(to=>{if(mediaBusy.value)return false;if(open.value&&dirty.value){return discard.decide(cancel)}})
</script>
<template><section class="surface-card official-content official-replies p-5 sm:p-7"><div class="flex flex-wrap gap-2"><UButton v-for="item in [{key:'keywords',label:'关键词回复'},{key:'fallback',label:'默认回复'},{key:'welcome',label:'关注回复'}]" :key="item.key" type="button" :color="tab===item.key?'primary':'neutral'" :variant="tab===item.key?'soft':'ghost'" @click="tab=item.key">{{item.label}}</UButton></div>
 <template v-if="tab==='keywords'"><UButton type="button" class="self-start" icon="i-lucide-plus" :disabled="disabled||model.keywords.length>=100" @click="edit()">新建回复</UButton><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="border-b border-default text-left text-muted"><tr><th class="p-3">规则名称</th><th class="p-3">关键词</th><th class="p-3">匹配规则</th><th class="p-3">回复方式</th><th class="p-3">操作</th></tr></thead><tbody><tr v-for="(row,index) in model.keywords" :key="row.id" class="border-b border-default"><td class="p-3">{{row.name}}</td><td class="p-3">{{row.keyword}}</td><td class="p-3">{{row.match==='exact'?'精确匹配':'包含关键词'}}</td><td class="p-3">{{({text:'文本',image:'图片',video:'视频',news:'图文',miniprogram:'小程序卡片'} as Record<string,string>)[row.type||'text']}}</td><td class="whitespace-nowrap p-3"><UButton type="button" variant="ghost" :disabled="disabled" @click="edit(row)">编辑</UButton><UButton type="button" variant="ghost" color="error" :disabled="disabled" @click="model.keywords.splice(index,1)">删除</UButton></td></tr><tr v-if="!model.keywords.length"><td colspan="5" class="p-8 text-center text-muted">暂无关键词回复</td></tr></tbody></table></div><p class="text-xs text-muted">按列表顺序匹配，命中第一条规则后回复。支持文本、图片、视频、图文和小程序卡片。</p></template>
 <template v-else><OfficialReplyEditor v-model="model[tab as 'welcome'|'fallback']" :disabled="disabled" @busy="pending"/><p class="text-xs text-muted">填写内容并保存后自动使用；清空内容后不回复。</p></template>
 </section><ConsoleDrawer :open="open" :title="editing?'编辑关键词回复':'新建关键词回复'" @update:open="!$event&&close()"><template #body><ConsoleValidatedForm id="official-reply-form" class="space-y-5" @submit="save" @invalid="error=$event"><UAlert v-if="error" color="error" :title="error"/><ConsoleSettingsField label="规则名称" input-id="reply-name"><ConsoleInput id="reply-name" v-model="draft.name" required :maxlength="60"/></ConsoleSettingsField><ConsoleSettingsField label="关键词" input-id="reply-keyword"><ConsoleInput id="reply-keyword" v-model="draft.keyword" required :maxlength="100"/></ConsoleSettingsField><ConsoleSettingsField label="匹配规则" input-id="reply-match"><USelect id="reply-match" v-model="draft.match" :items="[{label:'精确匹配',value:'exact'},{label:'包含关键词',value:'contains'}]"/></ConsoleSettingsField><OfficialReplyEditor v-model="draft" :disabled="disabled" @busy="pending"/></ConsoleValidatedForm></template><template #footer><ConsoleFormActions class="w-full"><UButton type="button" color="neutral" variant="outline" @click="close">取消</UButton><UButton type="submit" form="official-reply-form" :disabled="mediaBusy||disabled">确定</UButton></ConsoleFormActions></template></ConsoleDrawer><ConsoleDiscardChangesDialog :controller="discard"/>
</template>

<style scoped>.official-replies{display:flex;flex-direction:column;gap:1.25rem}.official-replies :deep(.official-reply-editor){flex:1}</style>
